11	  maxProducts?: number;
12	  pdpSample?: number;
13	  cacheDir?: string;
14	  noCache?: boolean;
15	  offlineFixturesDir?: string;
16	  config?: Partial<BeaconConfig>;
17	  now?: () => Date;
