23	/**
24	 * Scans a Shopify storefront (or replays fixtures via `offlineFixturesDir`) and returns
25	 * the normalised snapshot, sampled PDP markers, and the computed Findings. No I/O side
26	 * effects beyond the network fetches themselves — never prints, never writes files.
27	 */
28	export async function scanStore(storeUrl: string, opts: ScanOptions = {}): Promise<ScanResult> {
29	  const snapshot = opts.offlineFixturesDir
30	    ? await collectOffline(opts.offlineFixturesDir)
31	    : await collect(storeUrl, {
32	        maxProducts: opts.maxProducts,
33	        cacheDir: opts.cacheDir,
34	        noCache: opts.noCache,
35	        config: opts.config,
36	        onProgress: opts.onProgress,
37	      });
38	
39	  const markers = await samplePdpMarkers(snapshot, {
40	    pdpSample: opts.pdpSample,
41	    offlineFixturesDir: opts.offlineFixturesDir,
42	    cacheDir: opts.cacheDir,
43	    noCache: opts.noCache,
44	    onProgress: opts.onProgress,
45	  });
46	
47	  const findings = analyse(snapshot, markers, opts.config, undefined, opts.now);
48	
49	  return { snapshot, markers, findings };
50	}
51	
52	/** Pure: recompute Findings from an already-collected snapshot + markers. */
53	export function analyseSnapshot(
54	  snapshot: StoreSnapshot,
55	  markers: PdpMarkers,
56	  config?: Partial<BeaconConfig>,
57	  delta?: AvailabilityDelta,
58	): Findings {
59	  return analyse(snapshot, markers, config, delta);
60	}
61	
62	/** Pure: compare two snapshots and report availability flips (P1). */
63	export function diffSnapshots(a: StoreSnapshot, b: StoreSnapshot): AvailabilityDelta {
64	  return diff(a, b);
65	}
66	
67	/** Pure: render Findings into the three output formats as strings (no file writes). */
68	export function renderReport(findings: Findings): { html: string; csv: string; terminal: string } {
69	  return { html: renderHtml(findings), csv: toCsv(findings), terminal: toTerminal(findings) };
70	}
